using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Staff.Subway;
public static class SkyColorTwinkleSetup {
 [MenuItem("STAFF/Subway/Apply Sky Color And Twinkle")]
 public static void Install(){if(EditorApplication.isPlaying)throw new Exception("Exit Play mode first.");var sky=UnityEngine.Object.FindFirstObjectByType<SubwayTimeOfDay>();if(!sky)throw new Exception("Open subway scene.");Directory.CreateDirectory("Library/StaffSubway");EditorSceneManager.SaveScene(sky.gameObject.scene,"Library/StaffSubway/before-color-twinkle.unity",true);Undo.RecordObjects(new UnityEngine.Object[]{sky,sky.atmosphere},"Sky color and twinkle");var a=sky.atmosphere;a.elevationOzone=true;a.ozoneStartDegrees=10;a.ozoneMiddleDegrees=20;a.ozoneFullDegrees=60;a.horizonOzone=.6f;a.middleOzone=2.5f;a.noonOzone=50;sky.skyWeather.starSize=.65f;sky.skyWeather.starBrightness=.55f;sky.skyWeather.animate=true;a.Tick(true);sky.ApplySky();EditorUtility.SetDirty(a);EditorUtility.SetDirty(sky);EditorSceneManager.MarkSceneDirty(sky.gameObject.scene);EditorSceneManager.SaveScene(sky.gameObject.scene);Debug.Log("Sky color/twinkle saved: ozone 10/.6 20/2.5 60/50; stars .65 size .55 brightness.");}
}
